def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    zebras = image_patch.find("zebra")
    tents = image_patch.find("tent")

    if not zebras or not tents:
        return image_patch

    tent_depths = {t: t.compute_depth() for t in tents}
    closest_tent = min(tents, key=tent_depths.get)

    closest_zebra = min(zebras, key=lambda z: abs(z.compute_depth() - tent_depths[closest_tent]))

    return closest_zebra

